/**
 * 云端备份：把「我的文档」里的原文件放进 Supabase 存储桶，元数据写进
 * user_docs 表；换设备登录同一个备份账号就能拉回来。
 *
 * 这一层只认 Supabase 自己的登录 —— 文件是不是你的由 RLS（auth.uid()）
 * 判定，跟 Leafia 本机/后端的账号体系无关（用户 2026-10-14 选的方案）。
 */
import { notifyCloudAuthChanged } from "./cloudSync";
import {
  DOCUMENTS_BUCKET,
  DOCUMENTS_TABLE,
  getSupabase,
  supabaseConfigured,
} from "./supabase";
import { extensionOf, type ImportedDocument } from "./documentLibrary";

export interface CloudDocumentRow {
  id: string;
  user_id: string;
  file_name: string;
  file_type: string;
  storage_path: string;
  created_at: string;
}

export type CloudResult<T = undefined> =
  | { ok: true; value: T }
  | { ok: false; message: string };

export function cloudAvailable() {
  return supabaseConfigured();
}

const MIME_BY_EXTENSION: Record<string, string> = {
  pdf: "application/pdf",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  doc: "application/msword",
  pptx: "application/vnd.openxmlformats-officedocument.presentationml.presentation",
  ppt: "application/vnd.ms-powerpoint",
  epub: "application/epub+zip",
};

/** Supabase 的报错翻成人话：这几条是用户真会撞上的。 */
export function describeCloudError(error: unknown) {
  const raw =
    error && typeof error === "object" && "message" in error
      ? String((error as { message: unknown }).message)
      : String(error ?? "");
  if (/Invalid login credentials/i.test(raw)) return "邮箱或密码不对。";
  if (/Email not confirmed/i.test(raw)) {
    return "这个邮箱还没确认：去收件箱点一下确认链接，再回来登录。";
  }
  if (/User already registered/i.test(raw)) {
    return "这个邮箱已经注册过了，直接登录。";
  }
  if (/Password should be at least/i.test(raw)) return "密码太短：至少 6 位。";
  if (/row-level security/i.test(raw)) {
    return "云端规则拦下了这次写入：存储桶/数据表的 RLS 还没有允许本人读写。";
  }
  if (/Bucket not found/i.test(raw)) {
    return "找不到 user_documents 存储桶，检查一下 Supabase 里的桶名。";
  }
  if (/relation .* does not exist|Could not find the table/i.test(raw)) {
    return "找不到云端数据表（user_docs / user_sync），检查一下 Supabase 里的建库脚本跑过没有。";
  }
  if (/mime type|invalid_mime_type/i.test(raw)) {
    return "这个类型被存储桶的 MIME 白名单拦下了。";
  }
  if (/Failed to fetch|NetworkError/i.test(raw)) {
    return "连不上云端：检查网络，或稍后再试。";
  }
  return raw || "云端操作失败。";
}

function supabaseClient() {
  const instance = getSupabase();
  if (!instance) {
    throw new Error(
      "云端未配置：缺少 VITE_SUPABASE_URL / VITE_SUPABASE_ANON_KEY。",
    );
  }
  return instance;
}

export async function cloudAccount() {
  if (!supabaseConfigured()) return null;
  const instance = getSupabase();
  if (!instance) return null;
  const { data } = await instance.auth.getSession();
  const user = data.session?.user;
  if (!user) return null;
  return { id: user.id, email: user.email ?? "" };
}

export function onCloudAuthChange(listener: (email: string | null) => void) {
  if (!supabaseConfigured()) return () => {};
  const instance = getSupabase();
  if (!instance) return () => {};
  const { data } = instance.auth.onAuthStateChange((_event, session) => {
    listener(session?.user.email ?? null);
  });
  return () => data.subscription.unsubscribe();
}

export async function signInCloud(
  email: string,
  password: string,
): Promise<CloudResult> {
  try {
    const instance = supabaseClient();
    const { error } = await instance.auth.signInWithPassword({
      email,
      password,
    });
    if (error) throw error;
    // 登录这一下就是「登录即自动同步」的起点（见 lib/cloudSync.ts）。
    notifyCloudAuthChanged();
    return { ok: true, value: undefined };
  } catch (error) {
    return { ok: false, message: describeCloudError(error) };
  }
}

/**
 * 注册备份账号。Supabase 项目开着「邮箱确认」时，注册完还得去收件箱点一下
 * 链接才能登录 —— 这一步在对话框里明说，免得用户以为卡住了。
 */
export async function signUpCloud(
  email: string,
  password: string,
): Promise<CloudResult<{ needsConfirmation: boolean }>> {
  try {
    const instance = supabaseClient();
    const { data, error } = await instance.auth.signUp({ email, password });
    if (error) throw error;
    // 项目没开邮箱确认时注册即登录：云端同步该动了。
    if (data.session) notifyCloudAuthChanged();
    return { ok: true, value: { needsConfirmation: !data.session } };
  } catch (error) {
    return { ok: false, message: describeCloudError(error) };
  }
}

export async function signOutCloud(): Promise<CloudResult> {
  try {
    const instance = supabaseClient();
    const { error } = await instance.auth.signOut();
    if (error) throw error;
    notifyCloudAuthChanged();
    return { ok: true, value: undefined };
  } catch (error) {
    return { ok: false, message: describeCloudError(error) };
  }
}

/** user_id/文档 id.后缀 —— 存储桶的 RLS 就按第一层目录对 auth.uid()。 */
export function cloudObjectPath(userId: string, doc: ImportedDocument) {
  const extension = extensionOf(doc.fileName) || doc.fileType.toLowerCase();
  return `${userId}/${doc.id}.${extension}`;
}

export async function uploadDocumentToCloud(
  doc: ImportedDocument,
  blob: Blob,
): Promise<CloudResult<{ path: string }>> {
  try {
    const account = await cloudAccount();
    if (!account) return { ok: false, message: "先登录备份账号，再备份文档。" };
    const instance = supabaseClient();
    const path = cloudObjectPath(account.id, doc);
    const contentType =
      blob.type ||
      MIME_BY_EXTENSION[extensionOf(doc.fileName)] ||
      "application/octet-stream";

    const upload = await instance.storage
      .from(DOCUMENTS_BUCKET)
      .upload(path, blob, { upsert: true, contentType });
    if (upload.error) throw upload.error;

    // 元数据行：storage_path 是唯一能和存储桶对上的坐标。
    const inserted = await instance.from(DOCUMENTS_TABLE).upsert(
      {
        id: doc.id,
        user_id: account.id,
        file_name: doc.fileName,
        file_type: doc.fileType,
        storage_path: path,
        created_at: doc.createdAt,
      },
      { onConflict: "id" },
    );
    if (inserted.error) throw inserted.error;

    return { ok: true, value: { path } };
  } catch (error) {
    return { ok: false, message: describeCloudError(error) };
  }
}

export async function listCloudDocuments(): Promise<
  CloudResult<CloudDocumentRow[]>
> {
  try {
    const instance = supabaseClient();
    const { data, error } = await instance
      .from(DOCUMENTS_TABLE)
      .select("id,user_id,file_name,file_type,storage_path,created_at")
      .order("created_at", { ascending: false });
    if (error) throw error;
    return { ok: true, value: (data ?? []) as CloudDocumentRow[] };
  } catch (error) {
    return { ok: false, message: describeCloudError(error) };
  }
}

export async function downloadCloudDocument(
  path: string,
): Promise<CloudResult<Blob>> {
  try {
    const instance = supabaseClient();
    const { data, error } = await instance.storage
      .from(DOCUMENTS_BUCKET)
      .download(path);
    if (error) throw error;
    if (!data) throw new Error("云端没有这个文件。");
    return { ok: true, value: data };
  } catch (error) {
    return { ok: false, message: describeCloudError(error) };
  }
}

export async function deleteCloudDocument(
  row: CloudDocumentRow,
): Promise<CloudResult> {
  try {
    const instance = supabaseClient();
    const removed = await instance.storage
      .from(DOCUMENTS_BUCKET)
      .remove([row.storage_path]);
    if (removed.error) throw removed.error;
    const deleted = await instance
      .from(DOCUMENTS_TABLE)
      .delete()
      .eq("id", row.id);
    if (deleted.error) throw deleted.error;
    return { ok: true, value: undefined };
  } catch (error) {
    return { ok: false, message: describeCloudError(error) };
  }
}
