import { useCallback, useEffect, useState } from "react";
import { CloudDownload, CloudUpload, LoaderCircle, RefreshCw } from "lucide-react";
import {
  cloudAccount,
  cloudAvailable,
  deleteCloudDocument,
  downloadCloudDocument,
  listCloudDocuments,
  onCloudAuthChange,
  signInCloud,
  signOutCloud,
  signUpCloud,
  type CloudDocumentRow,
} from "../../lib/cloudDocuments";
import { useDocuments } from "../../store/documents";
import { useLeafia } from "../../store/leafia";
import "./documents.css";

/**
 * 备份账号的登录框。注册走 Supabase 自己的邮箱确认：注册完还要去收件箱点一下
 * 链接才能登录，对话框里直接把这句话说出来。
 *
 * hint：说明文字换一处场景就说一处的话（账号页的「云端同步」卡会用）。
 */
export function CloudAuthForm({
  onSignedIn,
  hint,
}: {
  onSignedIn?: (email: string) => void;
  hint?: string;
}) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [message, setMessage] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async (mode: "sign-in" | "sign-up") => {
    if (!email.trim() || !password) {
      setMessage("邮箱和密码都要填。");
      return;
    }
    setBusy(true);
    setMessage(null);
    // 两条路分开写：注册那条要读回 needsConfirmation（项目开了邮箱确认），
    // 登录那条没有返回值 —— 合在一个三元里 TS 说不清 value 是什么。
    if (mode === "sign-up") {
      const created = await signUpCloud(email.trim(), password);
      setBusy(false);
      if (!created.ok) {
        setMessage(created.message);
        return;
      }
      if (created.value.needsConfirmation) {
        setMessage("注册好了：去这个邮箱点一下确认链接，再回来登录。");
        return;
      }
      setMessage(null);
      onSignedIn?.(email.trim());
      return;
    }
    const signedIn = await signInCloud(email.trim(), password);
    setBusy(false);
    if (!signedIn.ok) {
      setMessage(signedIn.message);
      return;
    }
    setMessage(null);
    onSignedIn?.(email.trim());
  };

  return (
    <div className="doc-auth">
      <label className="doc-field">
        <span>备份账号邮箱</span>
        <input
          type="email"
          value={email}
          autoComplete="email"
          onChange={(event) => setEmail(event.target.value)}
          placeholder="you@example.com"
        />
      </label>
      <label className="doc-field">
        <span>密码</span>
        <input
          type="password"
          value={password}
          autoComplete="current-password"
          onChange={(event) => setPassword(event.target.value)}
          placeholder="至少 6 位"
        />
      </label>
      <div className="doc-page__actions">
        <button
          type="button"
          className="doc-button doc-button--primary"
          onClick={() => void submit("sign-in")}
          disabled={busy}
        >
          {busy ? <LoaderCircle size={15} className="doc-spin" /> : null}
          登录备份账号
        </button>
        <button
          type="button"
          className="doc-button"
          onClick={() => void submit("sign-up")}
          disabled={busy}
        >
          注册一个
        </button>
      </div>
      {message && <p className="doc-note doc-note--warn">{message}</p>}
      <p className="doc-note">
        {hint ??
          "存备份用的邮箱账号：登录后导入的文档和本机的学习成果都能存到云端，换设备登录就都还在；它跟 Leafia 的登录不是一回事。"}
      </p>
    </div>
  );
}

/**
 * 云端那一半：登录、看云端有什么、恢复到本机、从云端删掉。
 */
export function CloudBackupPanel() {
  const showToast = useLeafia((state) => state.showToast);
  const localDocuments = useDocuments((state) => state.documents);
  const importFile = useDocuments((state) => state.importFile);
  const patchCloud = useDocuments((state) => state.patchCloud);
  const [email, setEmail] = useState<string | null>(null);
  const [rows, setRows] = useState<CloudDocumentRow[]>([]);
  const [message, setMessage] = useState<string | null>(null);
  const [busyPath, setBusyPath] = useState<string | null>(null);

  const configured = cloudAvailable();

  const refresh = useCallback(async () => {
    const account = await cloudAccount();
    setEmail(account?.email ?? null);
    if (!account) {
      setRows([]);
      return;
    }
    const listed = await listCloudDocuments();
    if (!listed.ok) {
      setMessage(listed.message);
      setRows([]);
      return;
    }
    setMessage(null);
    setRows(listed.value);
  }, []);

  useEffect(() => {
    void refresh();
    return onCloudAuthChange(() => {
      void refresh();
    });
  }, [refresh]);

  const restore = async (row: CloudDocumentRow) => {
    setBusyPath(row.storage_path);
    setMessage(null);
    const downloaded = await downloadCloudDocument(row.storage_path);
    if (!downloaded.ok) {
      setBusyPath(null);
      setMessage(downloaded.message);
      return;
    }
    // 找回本机还是走同一条导入路：重新抽一次正文，顺带补上本地那份元数据。
    const file = new File([downloaded.value], row.file_name, {
      type: downloaded.value.type,
    });
    try {
      const { doc } = await importFile(file);
      patchCloud(doc.id, {
        status: "uploaded",
        path: row.storage_path,
        uploadedAt: row.created_at,
      });
      showToast(`已从云端恢复到本机：《${doc.title}》`);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "恢复失败。");
    }
    setBusyPath(null);
  };

  const remove = async (row: CloudDocumentRow) => {
    setBusyPath(row.storage_path);
    const removed = await deleteCloudDocument(row);
    setBusyPath(null);
    if (!removed.ok) {
      setMessage(removed.message);
      return;
    }
    showToast("已从云端删除。");
    await refresh();
  };

  if (!configured) {
    return (
      <section className="doc-card">
        <header>
          <h2>云端备份</h2>
          <small>Cloud backup</small>
        </header>
        <p className="doc-note">
          这份构建没有配云端（缺 VITE_SUPABASE_URL / VITE_SUPABASE_ANON_KEY），
          导入的文档只存在这台设备上。
        </p>
      </section>
    );
  }

  const localNames = new Set(localDocuments.map((doc) => doc.fileName));

  return (
    <section className="doc-card">
      <header>
        <h2>云端备份</h2>
        <small>{email ? `已登录 ${email}` : "Cloud backup"}</small>
      </header>

      {email ? (
        <div className="doc-page__actions">
          <button type="button" className="doc-button" onClick={() => void refresh()}>
            <RefreshCw size={15} />
            刷新云端清单
          </button>
          <button
            type="button"
            className="doc-button doc-button--quiet"
            onClick={() => {
              void signOutCloud().then(() => refresh());
            }}
          >
            退出备份账号
          </button>
        </div>
      ) : (
        <CloudAuthForm onSignedIn={() => void refresh()} />
      )}

      {email && (
        <ul className="doc-list">
          {rows.length === 0 && (
            <li className="doc-list__row is-empty">
              云端还没有文档：在本机那一列点「备份到云端」。
            </li>
          )}
          {rows.map((row) => (
            <li className="doc-list__row" key={row.id}>
              <div className="doc-list__main">
                <strong>{row.file_name}</strong>
                <small>
                  {row.file_type} ·{" "}
                  {new Date(row.created_at).toLocaleString("zh-CN")}
                </small>
              </div>
              {localNames.has(row.file_name) && (
                <span className="doc-tag doc-tag--muted">本机也有</span>
              )}
              <button
                type="button"
                className="doc-button"
                disabled={busyPath === row.storage_path}
                onClick={() => void restore(row)}
              >
                {busyPath === row.storage_path ? (
                  <LoaderCircle size={15} className="doc-spin" />
                ) : (
                  <CloudDownload size={15} />
                )}
                恢复到本机
              </button>
              <button
                type="button"
                className="doc-button doc-button--quiet doc-button--danger"
                disabled={busyPath === row.storage_path}
                onClick={() => void remove(row)}
              >
                从云端删除
              </button>
            </li>
          ))}
        </ul>
      )}

      {message && <p className="doc-note doc-note--warn">{message}</p>}
      <p className="doc-note">
        <CloudUpload size={13} /> 本机的文档只在这台设备上；点「备份到云端」
        会把它存进你自己的云端账号，换设备登录就能找回来，别人看不到。
      </p>
    </section>
  );
}
